INSERT OR IGNORE INTO "db_first_component_v2422" ("id","package_id","component_type","generation_mode","payload_json","source_basis","verified_alignment","runtime_enabled","status") VALUES (22,8,'RPH','database_template','{"sk_code": "2.3", "sp_code": "2.3.1", "sk_text": "Membaca dan mengapresiasi karya sastera dan bukan sastera", "sp_text": "Membaca dan mengenal pasti kandungan teks bahan sastera dan bukan sastera: (i) cerita; (ii) pantun; (iii) lagu kanak-kanak.", "topic": "2.0 Kemahiran Membaca", "objective": "Pada akhir pembelajaran, murid dapat menunjukkan pengetahuan atau kemahiran berdasarkan Standard Pembelajaran 2.3.1 melalui tugasan berpandu dan individu.", "success_criteria": "Murid melengkapkan tugasan sasaran dengan betul serta menunjukkan bukti penguasaan yang boleh diperhatikan atau disemak.", "prior_knowledge": "Murid mengingat semula pengetahuan atau pengalaman berkaitan 2.0 Kemahiran Membaca.", "induction": "Guru memperkenalkan situasi ringkas berkaitan 2.0 Kemahiran Membaca menggunakan bahan atau soalan yang sesuai.", "activities": "1. Guru memperkenalkan konteks bahasa yang dekat dengan murid. 2. Guru memberi satu contoh yang jelas. 3. Murid menjalankan latihan berpandu secara lisan atau bertulis. 4. Murid melaksanakan tugasan individu/pasangan berdasarkan standard. 5. Guru membincangkan jawapan dan memberi maklum balas.", "bbm": "Buku teks, kad perkataan/ayat, gambar, petikan pendek, papan mini dan lembaran kerja mengikut kesesuaian.", "assessment": "Pemerhatian guru, soal jawab dan semakan respons/hasil kerja murid berdasarkan Standard Pembelajaran.", "remediation": "Kurangkan bilangan item, beri contoh tambahan, petunjuk visual atau bimbingan langkah demi langkah.", "enrichment": "Berikan tugasan aplikasi, penaakulan atau respons lebih terbuka dalam skop Standard Pembelajaran yang sama.", "pak21": "Soal jawab berpandu, Think-Pair-Share, komunikasi dan semakan rakan apabila sesuai.", "emk_values": "Tanggungjawab, kerjasama, keyakinan, ketelitian dan hormat."}','curriculum_standards:8906 + curriculum_pedagogy:45 + rph_templates:45',1,0,'DB_READY');
