CREATE TABLE IF NOT EXISTS bm1_component_blueprint_v2423(
 id INTEGER PRIMARY KEY,
 sp_code TEXT NOT NULL, component TEXT NOT NULL,
 blueprint TEXT NOT NULL, requires_source_content INTEGER NOT NULL DEFAULT 1,
 db_generatable INTEGER NOT NULL DEFAULT 1, ready_status TEXT NOT NULL DEFAULT 'BLUEPRINT_READY',
 UNIQUE(sp_code,component)
);
INSERT OR IGNORE INTO "bm1_component_blueprint_v2423" ("id","sp_code","component","blueprint","requires_source_content","db_generatable","ready_status") VALUES (1,'1.1.1','RPH','Gunakan SK 1.1 dan SP 1.1.1 tepat. Objektif, kriteria kejayaan, aktiviti dan pentaksiran mesti mengukur kemahiran: Mengajuk, dan menyebut perkataan, frasa dan ayat yang mengandungi pelbagai bunyi: (i) vokal; (ii) konsonan; (iii) diftong; (iv) vokal berganding; (v) digraf; (vi) konsonan bergabung. Kandungan contoh hanya diisi selepas lesson/source dipadankan.',1,1,'BLUEPRINT_READY');
INSERT OR IGNORE INTO "bm1_component_blueprint_v2423" ("id","sp_code","component","blueprint","requires_source_content","db_generatable","ready_status") VALUES (2,'1.1.1','WORKSHEET','Format utama: respons lisan + item dengar/respons. Item mesti menguji SP 1.1.1: Mengajuk, dan menyebut perkataan, frasa dan ayat yang mengandungi pelbagai bunyi: (i) vokal; (ii) konsonan; (iii) diftong; (iv) vokal berganding; (v) digraf; (vi) konsonan bergabung. Jangan cipta perkataan/ayat/konteks sebelum sumber lesson diluluskan.',1,1,'BLUEPRINT_READY');
