CREATE TABLE IF NOT EXISTS bm1_dbfirst_package_v2424 (
 id INTEGER PRIMARY KEY AUTOINCREMENT, sp_code TEXT NOT NULL UNIQUE, sk_code TEXT, domain TEXT, sk_text TEXT, sp_text TEXT,
 rph_template_id INTEGER, pedagogy_id INTEGER, worksheet_mode TEXT NOT NULL, worksheet_structure TEXT NOT NULL,
