CREATE VIEW v_bm1_dbfirst_package_v2423 AS
SELECT d.sp_code,d.sk_code,d.topic,d.skill_family,d.sp_text,
 MAX(CASE WHEN b.component='RPH' THEN b.ready_status END) rph_status,
 MAX(CASE WHEN b.component='WORKSHEET' THEN b.ready_status END) worksheet_status,
 MAX(CASE WHEN b.component='BBM' THEN b.ready_status END) bbm_status,
 d.source_key,d.verified
FROM bm1_sp_delivery_v2423 d JOIN bm1_component_blueprint_v2423 b ON b.sp_code=d.sp_code
GROUP BY d.sp_code,d.sk_code,d.topic,d.skill_family,d.sp_text,d.source_key,d.verified;
DROP VIEW IF EXISTS "v_bm1_dbfirst_readiness_v2424";
CREATE VIEW v_bm1_dbfirst_readiness_v2424 AS SELECT sp_code,sk_code,domain,
 CASE WHEN rph_template_id IS NOT NULL THEN 1 ELSE 0 END rph_db_ready,
 CASE WHEN worksheet_structure<>'' THEN 1 ELSE 0 END worksheet_blueprint_ready,
 CASE WHEN bbm_structure<>'' THEN 1 ELSE 0 END bbm_plan_ready,
 content_lock,verified_standard,package_state FROM bm1_dbfirst_package_v2424;
COMMIT;